struct Requests final:a::Requests {a::RecoverySession* recovery{};rpc::CookieCredentials credentials;rpc::Transport transport{credentials};RefreshService refresh{[this](const auto& r,std::stop_token stop){return FetchRefresh(transport,r,stop);}};ConnectionService connection{[this](const auto& c,std::stop_token stop){return ProbeCapabilities(transport,c,stop);},[this](bool b){refresh.SetOffline(b,RefreshMonotonicMs());}};ConnectionService* Connection() override{return &connection;}RefreshService* Refresh() override{return &refresh;}a::RecoverySession* Recovery() override{return recovery;}a::HostObservations Observe() const override{return a::ConnectionObservations(connection,refresh);}a::Availability CanSubmit(const a::Request& r) const override{return {r.command==a::Command::Refresh,"Read-only refresh only"};}a::Receipt Submit(const a::Request& r) override{if(r.command==a::Command::Refresh)return {refresh.RequestNow(RefreshMonotonicMs()),"Read-only refresh"};throw std::runtime_error("unexpected host mutation");}};
struct Observer final:platform::NativeObserver {
    Requests requests;sh::State state;sh::Facts facts;std::filesystem::path out;Display* display{};void* xtst{};int(*motion)(Display*,int,int,int,unsigned long){};int(*button)(Display*,unsigned int,Bool,unsigned long){};int(*key)(Display*,unsigned int,Bool,unsigned long){};int checks{},stage{},base{};int64_t expected{};bool done{},cleaned{};std::set<std::string> selected;std::vector<std::string> keys;std::chrono::steady_clock::time_point started=std::chrono::steady_clock::now();
    void Check(bool b,const char* why){++checks;if(!b)throw std::runtime_error(why);}
    bool CaptureFramebuffer() const override{return true;}
    void Idle(platform::NativeHost&,const platform::NativeFrame&) override{if(std::chrono::steady_clock::now()-started>std::chrono::seconds(25))throw std::runtime_error("native coin deadline stage="+std::to_string(stage)+" history_error="+rpc::ErrorName(requests.refresh.View().errors[2]));}
    void Click(platform::NativeHost& host,const ui::components::ItemFacts& item,bool down){const auto& r=item.rect;if(!(item.visible && !item.disabled && r[0]>=0 && r[1]>=0 && r[2]<=960 && r[3]<=640))std::cerr<<"unreachable stage="<<stage<<" visible="<<item.visible<<" disabled="<<item.disabled<<" rect="<<r[0]<<","<<r[1]<<","<<r[2]<<","<<r[3]<<"\n";Check(item.visible && !item.disabled && r[0]>=0 && r[1]>=0 && r[2]<=960 && r[3]<=640,"native coin action reachable");int x{},y{};glfwGetWindowPos(host.Window(),&x,&y);Check(motion(display,-1,x+int((r[0]+r[2])/2),y+int((r[1]+r[3])/2),0),"native coin pointer");Check(button(display,1,down,0),"native coin click");XSync(display,False);}
    void Capture(const platform::NativeFrame& f,const char* name){std::ofstream file(out/(std::string(name)+".ppm"),std::ios::binary);file<<"P6\n"<<f.framebuffer_width<<' '<<f.framebuffer_height<<"\n255\n";for(int y=f.framebuffer_height-1;y>=0;--y)for(int x=0;x<f.framebuffer_width;++x)file.write(reinterpret_cast<const char*>(f.rgba.data()+(size_t(y)*f.framebuffer_width+x)*4),3);Check(bool(file),"coin framebuffer retained");Check(state.presentation.Tree().Validate() && !state.presentation.Tree().overflow,"coin semantics valid and bounded");std::ofstream(out/(std::string(name)+".semantics.txt"))<<state.presentation.Snapshot();}
    void Frame(platform::NativeHost& host,const platform::NativeFrame& f) override {
        auto* doc=state.documents.Find(1);if(!doc)return;
        if(stage==0){if(f.rendered_frames<4)return;Key(XK_Control_L,true);Key(XK_5,true);base=int(f.rendered_frames);stage=1;return;}
        if(stage==1 && int(f.rendered_frames)>base){Key(XK_5,false);Key(XK_Control_L,false);stage=2;return;}
        const auto history=a::HistoryForDocument(*doc,requests.refresh,{});
        if(stage==2){if(!history || !history->chain_current || !history->ledger->Complete() || !state.coins.contains(1) || !state.coins.at(1).inventory || facts.coin_order.size()<2)return;auto& inventory=*state.coins.at(1).inventory;Check(f.width==960 && f.height==640 && f.effective_scale==1.5F && !f.gl_error && f.font_texture,"actual native utxos960x640/150 percent");auto summary=inventory.Summary({});Check(summary.total && summary.total->sats()==expected,"exact observed coin sum matches authoritative wallet RPC");Check(summary.eligible && summary.eligible==history->ledger->Totals().rpc_fundable,"actual acknowledged empty local policy eligibility reconciles; no funding authority");bool immature=false;for(const auto& [key,row]:inventory.Rows())if(row.immature){immature=true;Check(row.eligible==false && row.reason.find("immature")!=std::string::npos,"actual immature coin readable with unavailable reason");}Check(immature,"actual fixture immature coin present");keys={facts.coin_order[0],facts.coin_order[1]};Capture(f,"utxos-unavailable");Click(host,facts.coin.at("row-"+keys[0]),true);base=int(f.rendered_frames);stage=3;return;}
        if(stage==3 && int(f.rendered_frames)>base){Click(host,facts.coin.at("row-"+keys[0]),false);base=int(f.rendered_frames);stage=4;return;}
        if(stage==4 && int(f.rendered_frames)>base+3){Check(doc->coins.Selection().contains(keys[0]),"first exact native selection");Click(host,facts.coin.at("row-"+keys[1]),true);base=int(f.rendered_frames);stage=5;return;}
        if(stage==5 && int(f.rendered_frames)>base){Click(host,facts.coin.at("row-"+keys[1]),false);base=int(f.rendered_frames);stage=6;return;}
        if(stage==6 && int(f.rendered_frames)>base+3){selected=doc->coins.Selection();if(selected.size()!=2){std::cerr<<"selection size="<<selected.size()<<" expected="<<keys[0]<<","<<keys[1]<<"\n";for(const auto& k:selected)std::cerr<<"selected="<<k<<"\n";Capture(f,"utxos-selection-failure");}Check(selected.size()==2,"native multi-selection exact outpoints");Check(doc->selected_coins.empty(),"presentation selection does not become draft inputs");Capture(f,"utxos-selection");Click(host,facts.coin.at("sort-value"),true);base=int(f.rendered_frames);stage=7;return;}
        if(stage==7 && int(f.rendered_frames)>base){Click(host,facts.coin.at("sort-value"),false);base=int(f.rendered_frames);stage=8;return;}
        if(stage==8 && int(f.rendered_frames)>base+3){Check(doc->coins.Selection()==selected,"native value sort retains exact selection");Capture(f,"utxos-sorted");std::ofstream(out/"disconnect")<<"owned read-only proxy failure boundary";Key(XK_Control_L,true);Key(XK_r,true);base=int(f.rendered_frames);stage=9;return;}
        if(stage==9 && int(f.rendered_frames)>base){Key(XK_r,false);Key(XK_Control_L,false);stage=10;return;}
        if(stage==10){if(!history || history->chain_current || requests.refresh.Busy())return;Check(doc->coins.Selection()==selected && facts.coin_order.size()>=2,"failed refresh retains exact selection and dated rows");Check(!state.coins.at(1).inventory->Summary(selected).selected_eligible,"stale selected eligibility Unknown");Capture(f,"utxos-stale");Key(XK_Control_L,true);Key(XK_Shift_L,true);Key(XK_h,true);base=int(f.rendered_frames);stage=11;return;}
        if(stage==11 && int(f.rendered_frames)>base){Key(XK_h,false);Key(XK_Shift_L,false);Key(XK_Control_L,false);base=int(f.rendered_frames);stage=12;return;}
        if(stage==12 && int(f.rendered_frames)>base+3){Check(state.privacy.hidden && facts.coin.at("sort-value").disabled,"native amount privacy disables financial sort");Check(state.presentation.ChartSamples().empty() && state.presentation.Snapshot().find("Observed coin value | Hidden")!=std::string::npos,"native coin amounts and chart concealed semantically");Capture(f,"utxos-hidden");requests.refresh.Unbind();stage=13;return;}
        if(stage==13 && !requests.refresh.Busy()){done=true;host.RequestClose();}
    }
    void Key(KeySym sym,bool down){Check(key(display,XKeysymToKeycode(display,sym),down,0),"native coin key");XSync(display,False);}
    void Teardown(const platform::NativeTeardown& t) override{cleaned=t.renderer_cleared && t.platform_cleared && t.textures_released && t.imgui_cleared && t.context_cleared;Check(cleaned,"native coin resources settled");}
};
